'use client';

// Reference component: this file establishes the pattern all components follow.
// - cva for variants, cn() for merging
// - semantic tokens only, via arbitrary-value classes bound to CSS vars
// - all states: hover, focus-visible (global ring), active, disabled, loading
// - min touch target 44px (A3)
// - cursor-pointer is explicit (A14): Tailwind v4's preflight sets buttons to
//   cursor: default, so every interactive component must opt back in

import * as React from 'react';
import { Slot, Slottable } from '@radix-ui/react-slot';
import { cva, type VariantProps } from 'class-variance-authority';
import { cn } from '@/lib/cn';

const buttonVariants = cva(
  [
    'inline-flex items-center justify-center gap-2 whitespace-nowrap select-none',
    'cursor-pointer rounded-[var(--radius-md)] font-medium',
    'transition-colors duration-[var(--duration-fast)]',
    'disabled:pointer-events-none disabled:cursor-not-allowed disabled:opacity-50',
    'min-h-[var(--touch-target-min)]',
    '[&_svg]:shrink-0',
  ],
  {
    variants: {
      variant: {
        primary: [
          'bg-[var(--color-action)] text-[var(--color-action-text)]',
          'hover:bg-[var(--color-action-hover)]',
          'active:opacity-90',
        ],
        secondary: [
          'bg-[var(--color-surface)] text-[var(--color-text-primary)]',
          'border border-[var(--color-border)]',
          'hover:bg-[var(--color-surface-hover)]',
          'active:bg-[var(--color-surface-active)]',
        ],
        ghost: [
          'text-[var(--color-text-primary)]',
          'hover:bg-[var(--color-surface-hover)]',
          'active:bg-[var(--color-surface-active)]',
        ],
        destructive: [
          'bg-[var(--color-status-error)] text-[var(--color-text-on-status)]',
          'hover:opacity-90 active:opacity-80',
        ],
      },
      size: {
        sm: 'h-9 min-h-9 px-3 text-[length:var(--text-sm)]',
        md: 'h-11 px-4 text-[length:var(--text-sm)]',
        lg: 'h-12 px-6 text-[length:var(--text-base)]',
        icon: 'h-11 w-11 p-0', // requires aria-label (A5)
      },
    },
    defaultVariants: { variant: 'primary', size: 'md' },
  }
);

export interface ButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof buttonVariants> {
  asChild?: boolean;
  loading?: boolean;
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant, size, asChild = false, loading = false, disabled, children, ...props }, ref) => {
    const Comp = asChild ? Slot : 'button';
    return (
      <Comp
        className={cn(buttonVariants({ variant, size }), className)}
        ref={ref}
        disabled={disabled || loading}
        aria-busy={loading || undefined}
        {...props}
      >
        {loading && (
          <span
            aria-hidden="true"
            className="size-4 animate-spin rounded-full border-2 border-current border-t-transparent"
          />
        )}
        {/* Slottable marks which child Slot merges into when asChild, so the
            loading sibling above no longer breaks the single-child rule. */}
        <Slottable>{children}</Slottable>
      </Comp>
    );
  }
);
Button.displayName = 'Button';

export { Button, buttonVariants };

"use client"

import * as React from "react"
import {
  DayPicker,
  DayButton,
  getDefaultClassNames,
  type Locale,
} from "react-day-picker"

import { cn } from "@/lib/cn"
import { buttonVariants, type ButtonProps } from "@/components/ui/button"
import { ChevronDown, ChevronLeft, ChevronRight } from "@/components/base-ds-icons/date-picker"

function Calendar({
  className,
  classNames,
  showOutsideDays = true,
  captionLayout = "label",
  buttonVariant = "ghost",
  locale,
  formatters,
  components,
  ...props
}: React.ComponentProps<typeof DayPicker> & {
  buttonVariant?: ButtonProps["variant"]
}) {
  const defaultClassNames = getDefaultClassNames()

  return (
    <DayPicker
      showOutsideDays={showOutsideDays}
      className={cn(
        "group/calendar bg-[var(--color-surface)] p-[var(--space-2)] text-[var(--color-text-primary)]",
        "[--cell-radius:var(--radius-sm)] [--cell-size:var(--touch-target-min)]",
        String.raw`rtl:**:[.rdp-button\_next>svg]:rotate-180`,
        String.raw`rtl:**:[.rdp-button\_previous>svg]:rotate-180`,
        className
      )}
      captionLayout={captionLayout}
      locale={locale}
      formatters={{
        formatMonthDropdown: (date) =>
          date.toLocaleString(locale?.code, { month: "short" }),
        ...formatters,
      }}
      classNames={{
        root: cn("w-fit", defaultClassNames.root),
        months: cn(
          "relative flex flex-col gap-[var(--space-4)] md:flex-row",
          defaultClassNames.months
        ),
        month: cn("flex w-full flex-col gap-[var(--space-4)]", defaultClassNames.month),
        nav: cn(
          "absolute inset-x-0 top-0 flex w-full items-center justify-between gap-[var(--space-1)]",
          defaultClassNames.nav
        ),
        button_previous: cn(
          buttonVariants({ variant: buttonVariant, size: "icon" }),
          "size-(--cell-size) min-h-(--cell-size) cursor-pointer p-0 select-none aria-disabled:cursor-not-allowed aria-disabled:opacity-50",
          defaultClassNames.button_previous
        ),
        button_next: cn(
          buttonVariants({ variant: buttonVariant, size: "icon" }),
          "size-(--cell-size) min-h-(--cell-size) cursor-pointer p-0 select-none aria-disabled:cursor-not-allowed aria-disabled:opacity-50",
          defaultClassNames.button_next
        ),
        month_caption: cn(
          "flex h-(--cell-size) w-full items-center justify-center px-(--cell-size)",
          defaultClassNames.month_caption
        ),
        dropdowns: cn(
          "flex h-(--cell-size) w-full items-center justify-center gap-[var(--space-2)] text-[length:var(--text-sm)] font-medium",
          defaultClassNames.dropdowns
        ),
        dropdown_root: cn(
          "relative rounded-[var(--cell-radius)]",
          defaultClassNames.dropdown_root
        ),
        dropdown: cn(
          "absolute inset-0 cursor-pointer bg-[var(--color-surface-raised)] opacity-0",
          defaultClassNames.dropdown
        ),
        caption_label: cn(
          "font-medium select-none text-[var(--color-text-primary)]",
          captionLayout === "label"
            ? "text-[length:var(--text-sm)]"
            : "flex min-h-[var(--touch-target-min)] items-center gap-[var(--space-1)] rounded-[var(--cell-radius)] px-[var(--space-2)] text-[length:var(--text-sm)] [&>svg]:size-4 [&>svg]:text-[var(--color-text-tertiary)]",
          defaultClassNames.caption_label
        ),
        month_grid: cn("w-full border-collapse", defaultClassNames.month_grid),
        weekdays: cn("flex", defaultClassNames.weekdays),
        weekday: cn(
          "flex-1 rounded-[var(--cell-radius)] text-[length:var(--text-sm)] font-normal text-[var(--color-text-secondary)] select-none",
          defaultClassNames.weekday
        ),
        week: cn("mt-[var(--space-2)] flex w-full", defaultClassNames.week),
        week_number_header: cn(
          "w-(--cell-size) select-none",
          defaultClassNames.week_number_header
        ),
        week_number: cn(
          "text-[length:var(--text-sm)] text-[var(--color-text-secondary)] select-none",
          defaultClassNames.week_number
        ),
        day: cn(
          "group/day relative aspect-square h-full w-full rounded-[var(--cell-radius)] p-0 text-center select-none [&:last-child[data-selected=true]_button]:rounded-r-[var(--cell-radius)]",
          props.showWeekNumber
            ? "[&:nth-child(2)[data-selected=true]_button]:rounded-l-[var(--cell-radius)]"
            : "[&:first-child[data-selected=true]_button]:rounded-l-[var(--cell-radius)]",
          defaultClassNames.day
        ),
        range_start: cn(
          "relative isolate rounded-l-[var(--cell-radius)] bg-[var(--color-brand-subtle)] after:absolute after:inset-y-0 after:right-0 after:w-[var(--space-4)] after:bg-[var(--color-brand-subtle)]",
          defaultClassNames.range_start
        ),
        range_middle: cn("rounded-none", defaultClassNames.range_middle),
        range_end: cn(
          "relative isolate rounded-r-[var(--cell-radius)] bg-[var(--color-brand-subtle)] after:absolute after:inset-y-0 after:left-0 after:w-[var(--space-4)] after:bg-[var(--color-brand-subtle)]",
          defaultClassNames.range_end
        ),
        today: cn(
          "rounded-[var(--cell-radius)] bg-[var(--color-surface-sunken)] text-[var(--color-text-primary)] data-[selected=true]:rounded-none",
          defaultClassNames.today
        ),
        outside: cn(
          "text-[var(--color-text-tertiary)] aria-selected:text-[var(--color-text-secondary)]",
          defaultClassNames.outside
        ),
        disabled: cn(
          "cursor-not-allowed text-[var(--color-text-disabled)] opacity-50",
          defaultClassNames.disabled
        ),
        hidden: cn("invisible", defaultClassNames.hidden),
        ...classNames,
      }}
      components={{
        Root: ({ className, rootRef, ...props }) => {
          return (
            <div
              data-slot="calendar"
              ref={rootRef}
              className={cn(className)}
              {...props}
            />
          )
        },
        Chevron: ({ className, orientation, ...props }) => {
          if (orientation === "left") {
            return (
              <ChevronLeft className={cn("size-4", className)} aria-hidden="true" {...props} />
            )
          }

          if (orientation === "right") {
            return (
              <ChevronRight className={cn("size-4", className)} aria-hidden="true" {...props} />
            )
          }

          return (
            <ChevronDown className={cn("size-4", className)} aria-hidden="true" {...props} />
          )
        },
        DayButton: ({ ...props }) => (
          <CalendarDayButton locale={locale} {...props} />
        ),
        WeekNumber: ({ children, ...props }) => {
          return (
            <td {...props}>
              <div className="flex size-(--cell-size) items-center justify-center text-center">
                {children}
              </div>
            </td>
          )
        },
        ...components,
      }}
      {...props}
    />
  )
}

function CalendarDayButton({
  className,
  day,
  modifiers,
  locale,
  ...props
}: React.ComponentProps<typeof DayButton> & { locale?: Partial<Locale> }) {
  const defaultClassNames = getDefaultClassNames()

  const ref = React.useRef<HTMLButtonElement>(null)
  React.useEffect(() => {
    if (modifiers.focused) ref.current?.focus()
  }, [modifiers.focused])

  return (
    <button
      ref={ref}
      data-day={day.date.toLocaleDateString(locale?.code)}
      data-selected-single={
        modifiers.selected &&
        !modifiers.range_start &&
        !modifiers.range_end &&
        !modifiers.range_middle
      }
      data-range-start={modifiers.range_start}
      data-range-end={modifiers.range_end}
      data-range-middle={modifiers.range_middle}
      className={cn(
        "relative isolate flex aspect-square size-auto min-h-(--cell-size) w-full min-w-(--cell-size) cursor-pointer flex-col gap-[var(--space-1)] border-0 leading-none font-normal",
        "rounded-[var(--cell-radius)] text-[length:var(--text-sm)] text-[var(--color-text-primary)] transition-colors duration-[var(--duration-fast)]",
        "hover:bg-[var(--color-surface-hover)] active:bg-[var(--color-surface-active)] disabled:cursor-not-allowed disabled:opacity-50",
        "group-data-[focused=true]/day:ring-2 group-data-[focused=true]/day:ring-[var(--color-focus-ring)]",
        "data-[range-end=true]:rounded-[var(--cell-radius)] data-[range-end=true]:rounded-r-[var(--cell-radius)] data-[range-end=true]:bg-[var(--color-action)] data-[range-end=true]:text-[var(--color-action-text)]",
        "data-[range-middle=true]:rounded-none data-[range-middle=true]:bg-[var(--color-brand-subtle)] data-[range-middle=true]:text-[var(--color-text-primary)]",
        "data-[range-start=true]:rounded-[var(--cell-radius)] data-[range-start=true]:rounded-l-[var(--cell-radius)] data-[range-start=true]:bg-[var(--color-action)] data-[range-start=true]:text-[var(--color-action-text)]",
        "data-[selected-single=true]:bg-[var(--color-action)] data-[selected-single=true]:text-[var(--color-action-text)] [&>span]:text-[length:var(--text-sm)] [&>span]:opacity-70",
        defaultClassNames.day,
        className
      )}
      {...props}
    />
  )
}

export { Calendar, CalendarDayButton }

'use client';

import * as React from 'react';
import type { DateRange } from 'react-day-picker';
import { Calendar as CalendarIcon } from '@/components/base-ds-icons/date-picker';
import { cn } from '@/lib/cn';
import { Button } from '@/components/ui/button';
import { Calendar } from '@/components/ui/calendar';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';

interface DatePickerProps {
  value?: Date;
  onValueChange?: (date: Date | undefined) => void;
  label?: string;
  placeholder?: string;
  disabled?: boolean;
  className?: string;
}

function DatePicker({
  value,
  onValueChange,
  label = 'Choose date',
  placeholder = 'Select date',
  disabled,
  className,
}: DatePickerProps) {
  return (
    <div className={cn('w-full', className)}>
      <Popover>
        <PopoverTrigger asChild>
          <Button type="button" variant="secondary" disabled={disabled} aria-label={label}>
            <CalendarIcon size={16} aria-hidden="true" />
            <span className={!value ? 'text-[var(--color-text-tertiary)]' : undefined}>
              {value ? value.toLocaleDateString() : placeholder}
            </span>
          </Button>
        </PopoverTrigger>
        <PopoverContent className="w-auto p-[var(--space-2)]" align="start">
          <Calendar mode="single" selected={value} onSelect={onValueChange} autoFocus />
        </PopoverContent>
      </Popover>
    </div>
  );
}

interface DateRangePickerProps extends Omit<DatePickerProps, 'value' | 'onValueChange'> {
  value?: DateRange;
  onValueChange?: (range: DateRange | undefined) => void;
}

function DateRangePicker({ value, onValueChange, label = 'Choose date range', placeholder = 'Select dates', disabled, className }: DateRangePickerProps) {
  const valueLabel = value?.from
    ? value.to
      ? `${value.from.toLocaleDateString()} to ${value.to.toLocaleDateString()}`
      : value.from.toLocaleDateString()
    : placeholder;

  return (
    <div className={cn('w-full', className)}>
      <Popover>
        <PopoverTrigger asChild>
          <Button type="button" variant="secondary" disabled={disabled} aria-label={label}>
            <CalendarIcon size={16} aria-hidden="true" />
            <span className={!value?.from ? 'text-[var(--color-text-tertiary)]' : undefined}>{valueLabel}</span>
          </Button>
        </PopoverTrigger>
        <PopoverContent className="w-auto p-[var(--space-2)]" align="start">
          <Calendar mode="range" selected={value} onSelect={onValueChange} numberOfMonths={2} autoFocus />
        </PopoverContent>
      </Popover>
    </div>
  );
}

export { DatePicker, DateRangePicker };
export type { DatePickerProps, DateRangePickerProps };

'use client';

import * as React from 'react';
import { Popover as PopoverPrimitive } from 'radix-ui';

import { cn } from '@/lib/cn';

const Popover = PopoverPrimitive.Root;
const PopoverTrigger = PopoverPrimitive.Trigger;
const PopoverAnchor = PopoverPrimitive.Anchor;

function PopoverContent({ className, align = 'center', sideOffset = 4, ...props }: React.ComponentProps<typeof PopoverPrimitive.Content>) {
  return (
    <PopoverPrimitive.Portal>
      <PopoverPrimitive.Content
        data-slot="popover-content"
        align={align}
        sideOffset={sideOffset}
        className={cn(
          'z-[var(--z-dropdown)] flex w-72 origin-[var(--radix-popover-content-transform-origin)] flex-col',
          'gap-[var(--space-3)] rounded-[var(--radius-lg)] border border-[var(--color-border)]',
          'bg-[var(--color-surface-raised)] p-[var(--space-4)] text-[length:var(--text-sm)] text-[var(--color-text-primary)] shadow-[var(--shadow-md)]',
          'duration-[var(--duration-base)] ease-[var(--ease-out)]',
          'data-[state=open]:animate-in data-[state=open]:fade-in-0 data-[state=open]:zoom-in-95',
          'data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=closed]:zoom-out-95',
          className
        )}
        {...props}
      />
    </PopoverPrimitive.Portal>
  );
}

function PopoverHeader({ className, ...props }: React.ComponentProps<'div'>) {
  return <div data-slot="popover-header" className={cn('flex flex-col gap-[var(--space-1)]', className)} {...props} />;
}

function PopoverTitle({ className, ...props }: React.ComponentProps<'h2'>) {
  return <h2 data-slot="popover-title" className={cn('font-medium text-[var(--color-text-primary)]', className)} {...props} />;
}

function PopoverDescription({ className, ...props }: React.ComponentProps<'p'>) {
  return <p data-slot="popover-description" className={cn('text-[var(--color-text-secondary)]', className)} {...props} />;
}

export { Popover, PopoverAnchor, PopoverContent, PopoverDescription, PopoverHeader, PopoverTitle, PopoverTrigger };

import { clsx, type ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

export {
  Calendar as CalendarIcon,
  ChevronDown,
  ChevronLeft,
  ChevronRight,
} from '@carbon/icons-react';
